WITH base AS (SELECT *, status_bits * humidity AS status_bits_times_humidity FROM device_readings WHERE reading_ts >= TIMESTAMP '2025-09-01 02:00:00' AND pressure < 1007), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits, id) AS latest_rank FROM base) t WHERE latest_rank = 1), metrics AS (SELECT id, device_code, reading_ts, humidity, pressure, status_bits, firmware, latest_rank, LAG(status_bits) OVER (PARTITION BY device_code ORDER BY temp_c, id) AS prev_status_bits, LEAD(status_bits) OVER (PARTITION BY device_code ORDER BY temp_c, id) AS next_status_bits, LEAD(status_bits_times_humidity) OVER (PARTITION BY device_code ORDER BY temp_c, id) AS next_status_bits_times_humidity, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY temp_c, id) AS event_seq FROM ranked), kept_keys AS (SELECT firmware, device_code FROM metrics EXCEPT DISTINCT SELECT firmware, device_code FROM device_readings WHERE device_code = 'DV-03'), verified AS (SELECT s.* FROM metrics s INNER JOIN kept_keys k ON s.firmware = k.firmware AND s.device_code = k.device_code), scored AS (SELECT device_code, reading_ts, latest_rank, next_status_bits_times_humidity, COUNT(prev_status_bits) OVER (ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS prev_status_bits_count_1h, AVG(prev_status_bits) OVER (PARTITION BY device_code ORDER BY CAST(reading_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW) AS prev_status_bits_avg_2h FROM verified), valid AS (SELECT *, CASE WHEN prev_status_bits_count_1h >= 13 THEN 'High' WHEN prev_status_bits_count_1h >= 6 THEN 'Medium' ELSE 'Low' END AS prev_status_bits_count_1h_band FROM scored WHERE device_code <> 'DV-01'), stats AS (SELECT device_code, CASE WHEN prev_status_bits_count_1h >= 14 THEN 'HIGH' ELSE 'LOW' END AS prev_status_bits_count_1h_tier, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, ROUND(SUM(next_status_bits_times_humidity) / NULLIF(COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END), 0), 2) AS next_status_bits_times_humidity_per_dv_02, COUNT(DISTINCT device_code) AS distinct_device_codes, ROUND(SUM(prev_status_bits_count_1h) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS prev_status_bits_count_1h_per_dv_04, SUM(CASE WHEN device_code = 'DV-02' THEN next_status_bits_times_humidity ELSE 0 END) AS dv_02_next_status_bits_times_humidity, GROUPING(device_code) AS grouping_level FROM valid GROUP BY GROUPING SETS ((device_code, CASE WHEN prev_status_bits_count_1h >= 14 THEN 'HIGH' ELSE 'LOW' END), (device_code))) SELECT device_code, prev_status_bits_count_1h_tier, device_code_list, next_status_bits_times_humidity_per_dv_02, distinct_device_codes, prev_status_bits_count_1h_per_dv_04, grouping_level, CASE WHEN device_code RLIKE '^(DV-03|DV-02)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS device_code_zone FROM stats ORDER BY prev_status_bits_count_1h_per_dv_04 NULLS FIRST, prev_status_bits_count_1h_tier;
